"""Serialize manually selected reading alarms and checked endpoint links.

No proposed reading edits a transcription. Mathematics indicates what to check;
the scan remains the sole authority for deciding the ink.
"""
from pathlib import Path
import json,csv
B=Path(__file__).resolve().parents[1]; O=B/'parts/root'
items={int(x['id'].split('-')[-1]):x for x in json.loads((O/'items.json').read_text())}
rows=[]; links=[]; projects=[]
P='SA18_texts/pro/MPL_11_043-058+56_transcription.tex'
K='SA18_texts/codex/K55-01_transcription.tex'
def R(c,s,l,reading,alternative,evidence,weight='high',confidence='medium',file=None):
    rows.append(dict(cote=c,scan=s,line=f'{file or (K if c==55 else P)}:{l}',reading=reading,alternative=alternative,evidence=evidence+' No ink decision is made in this run.',weight=weight,confidence=confidence))
def L(kind,fr,to,what,evidence,ns):
    sources=list(dict.fromkeys(s for n in ns for s in items[n]['sources']))
    row=dict(kind=kind,**{'from':fr,'to':to},what=what,evidence=evidence,note_ids='; '.join(sources))
    (projects if kind=='our projects' else links).append(row)

